using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;
namespace MuseReach {internal sealed class StatusPill:Control {
 public StatusPill(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.SupportsTransparentBackColor,true);AccessibleRole=AccessibleRole.StaticText;BackColor=Color.Transparent;ForeColor=Color.FromArgb(161,166,176);AutoSize=true;Text="正在检查";}
 public override Size GetPreferredSize(Size proposedSize){var s=TextRenderer.MeasureText(Text,Font);return new Size(s.Width+32,s.Height+10);}
 protected override void OnTextChanged(EventArgs e){base.OnTextChanged(e);AccessibleName=Text;Size=GetPreferredSize(Size.Empty);Invalidate();}
 protected override void OnFontChanged(EventArgs e){base.OnFontChanged(e);Size=GetPreferredSize(Size.Empty);}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;float h=Height-1,w=Width-1,r=h;using var p=new GraphicsPath();p.AddArc(0,0,r,r,90,180);p.AddArc(w-r,0,r,r,270,180);p.CloseFigure();using var fill=new SolidBrush(Color.FromArgb(23,117,215,187));using var border=new Pen(Color.FromArgb(65,117,215,187));g.FillPath(fill,p);g.DrawPath(border,p);var color=Text=="通道正常"?Color.FromArgb(117,215,187):Text=="通道中断"?Color.FromArgb(241,139,146):Text=="疑似假死"?Color.FromArgb(234,193,127):ForeColor;float cx=13f,cy=Height/2f;if(Text=="通道正常"){using var pen=new Pen(color,1.7f){StartCap=LineCap.Round,EndCap=LineCap.Round};g.DrawLine(pen,cx-4,cy,cx-1,cy+3);g.DrawLine(pen,cx-1,cy+3,cx+5,cy-4);}else if(Text=="通道中断"){using var pen=new Pen(color,1.7f){StartCap=LineCap.Round,EndCap=LineCap.Round};g.DrawLine(pen,cx-3.5f,cy-3.5f,cx+3.5f,cy+3.5f);g.DrawLine(pen,cx+3.5f,cy-3.5f,cx-3.5f,cy+3.5f);}else if(Text=="疑似假死"){using var pen=new Pen(color,1.5f){StartCap=LineCap.Round,EndCap=LineCap.Round};g.DrawEllipse(pen,cx-5,cy-5,10,10);g.DrawLine(pen,cx,cy,cx,cy-3.5f);g.DrawLine(pen,cx,cy,cx+2.5f,cy+1.5f);}else{using var dot=new SolidBrush(color);g.FillEllipse(dot,9,(Height-7)/2,7,7);}TextRenderer.DrawText(g,Text,Font,new Rectangle(22,0,Width-26,Height),ForeColor,TextFormatFlags.VerticalCenter|TextFormatFlags.NoPadding);}
}}
